void OnlineBrowser::rebuildChips(){
    chips.clear();int x=0;auto addChip=[this,&x](juce::String label,std::function<void()> remove){auto b=std::make_unique<juce::TextButton>(label+ui::text(" ×"));ui::buttonStyle(*b,"tonal");int width=juce::jlimit(80,240,36+int(label.length())*10);b->setBounds(x,0,width,30);x+=width+8;b->setTooltip(ui::text("清除此筛选：")+label);b->onClick=[this,remove]{juce::MessageManager::callAsync(callbacks.wrap([this,remove]{{juce::ScopedValueSetter<bool> guard(updating,true);remove();}searchCatalog();}));};chipStrip.addAndMakeVisible(*b);chips.push_back(std::move(b));};
    if(gear.getSelectedId()>1)addChip(gear.getText(),[this]{gear.setSelectedId(1,juce::dontSendNotification);});
    if(source.getSelectedId()==1){if(format.getSelectedId()>1)addChip(format.getText(),[this]{format.setSelectedId(1,juce::dontSendNotification);});if(architecture.getSelectedId()>1)addChip(architecture.getText(),[this]{architecture.setSelectedId(1,juce::dontSendNotification);});if(verified.getToggleState())addChip(ui::text("认证作者"),[this]{verified.setToggleState(false,juce::dontSendNotification);});if(calibrated.getToggleState())addChip(ui::text("已校准"),[this]{calibrated.setToggleState(false,juce::dontSendNotification);});
        for(auto* field:{&tags,&makes,&creators})for(auto& v:values(field->getText()))addChip(v,[field,v]{auto a=values(field->getText());a.removeString(v);field->setText(a.joinIntoString(", "),false);});}
    chipStrip.setSize(x,32);resized();
}
void OnlineBrowser::resetFilters(){
    {juce::ScopedValueSetter<bool> guard(updating,true);query.clear();tags.clear();makes.clear();creators.clear();source.setSelectedId(client.isConnected()?1:6,juce::dontSendNotification);gear.setSelectedId(1,juce::dontSendNotification);format.setSelectedId(1,juce::dontSendNotification);architecture.setSelectedId(1,juce::dontSendNotification);sort.setSelectedId(2,juce::dontSendNotification);verified.setToggleState(false,juce::dontSendNotification);calibrated.setToggleState(false,juce::dontSendNotification);}searchCatalog();
}
void OnlineBrowser::chooseFilter(int kind){
    if(!client.isConnected() || demo)return;auto* anchor=kind==0?&tagPicker:kind==1?&makePicker:&creatorPicker;
    auto picker=std::make_unique<FilterPicker>(client,kind,callbacks.wrap([this,kind](juce::String value){auto* field=kind==0?&tags:kind==1?&makes:&creators;auto items=values(field->getText());items.addIfNotAlreadyThere(value);field->setText(items.joinIntoString(", "),false);searchCatalog();}));picker->setSize(juce::jmin(380,getWidth()-48),400);juce::CallOutBox::launchAsynchronously(std::move(picker),getLocalArea(anchor,anchor->getLocalBounds()),this);
}
bool OnlineBrowser::readyKey(){if(client.publishableKey().isNotEmpty())return true;if(processor.services->configureKey(key.getText())){key.setReadOnly(true);return true;}accountExpanded=true;filtersExpanded=false;resized();state.setText(ui::text("请先填写 TONE3000 的 t3k_pub_ 公开 Key。"),juce::dontSendNotification);return false;}
void OnlineBrowser::authenticate(t3k::FlowRequest::Kind kind,int id,juce::String target){
    if(!readyKey())return;if(flow)flow->cancel();flow=t3k::makeAuthFlow(t3k::FlowMode::systemBrowser);t3k::FlowRequest request;request.kind=kind;request.catalog.preview=true;if(id>0)request.toneId=juce::String(id);state.setText(ui::text("请在浏览器完成登录，完成后会自动返回。"),juce::dontSendNotification);
    try{flow->start(request,callbacks.wrap([this,target](t3k::FlowResult r){if(!r.connected()){state.setText(r.canceled()?ui::text("Canceled"):ui::message(r.error),juce::dontSendNotification);return;}accountExpanded=false;source.setSelectedId(1,juce::dontSendNotification);resized();searchCatalog();if(r.toneId.getIntValue()>0)openTone(r.toneId.getIntValue(),true,target);}));}catch(const std::exception& e){state.setText(ui::message(juce::String::fromUTF8(e.what())),juce::dontSendNotification);}
}
void OnlineBrowser::searchCatalog(){
    if(demo || catalog.isLoading())return;if(!client.isConnected() && source.getSelectedId()!=6 && source.getSelectedId()!=7){state.setText(ui::text("Connect TONE3000 first"),juce::dontSendNotification);return;}auto text=source.getSelectedId()==6?juce::String():query.getText().trim();if(auto id=parseToneLink(text)){openTone(*id);return;}
    CatalogQuery q;q.source=static_cast<CatalogQuery::Source>(source.getSelectedId()-1);q.filters.query=text;auto gearId=gear.getSelectedId()-2;if(gearId>=0 && gearId<t3k::gear::all.size())q.filters.gears.add(t3k::gear::all[gearId]);const juce::StringArray formats{"","nam","ir","aida-x","aa-snapshot","proteus"};q.filters.format=formats[juce::jlimit(0,formats.size()-1,format.getSelectedId()-1)];q.architecture=architecture.getSelectedId()==2?2:architecture.getSelectedId()==3?1:0;
    if(text.isEmpty() && sort.getSelectedId()==1)sort.setSelectedId(2,juce::dontSendNotification);const juce::StringArray sorts{"best-match","trending","downloads-all-time","newest","oldest"};q.filters.sort=sorts[juce::jlimit(0,4,sort.getSelectedId()-1)];q.filters.tags=values(tags.getText());q.filters.makes=values(makes.getText());q.filters.creators=values(creators.getText());q.filters.verified=verified.getToggleState();q.filters.calibrated=calibrated.getToggleState();started=true;rebuildChips();catalog.search(std::move(q));
}
void OnlineBrowser::openTone(int id,bool autoLoad,juce::String target){if(!client.isConnected()){authenticate(t3k::FlowRequest::Kind::loadTone,id,target);return;}catalog.select(id);if(autoLoad)load(id,0,target);}
void OnlineBrowser::update(){
    juce::ScopedValueSetter<bool> guard(updating,true);list.updateContent();for(int i=0;i<catalog.tones().size();++i)if(catalog.tones()[i].id==catalog.selectedId()){list.selectRow(i,true,true);break;}
    bool connected=client.isConnected() && !demo,full=source.getSelectedId()==1,canSearch=!demo && !catalog.isLoading() && (connected || source.getSelectedId()==6 || source.getSelectedId()==7);query.setEnabled(canSearch && source.getSelectedId()!=6);for(int id=1;id<=5;++id)source.setItemEnabled(id,connected || demo);searchButton.setEnabled(canSearch);source.setEnabled(!demo && !catalog.isLoading());gear.setEnabled(canSearch);more.setEnabled(canSearch && catalog.hasMore());previous.setEnabled(canSearch && catalog.page()>1);next.setEnabled(canSearch && catalog.page()<catalog.pages());filters.setEnabled(canSearch || filtersExpanded);clear.setEnabled(canSearch);for(auto& b:chips)b->setEnabled(canSearch);for(auto* c:std::initializer_list<juce::Component*>{&format,&architecture,&sort,&tags,&makes,&creators,&verified,&calibrated,&tagPicker,&makePicker,&creatorPicker})c->setEnabled(full && canSearch);
    count.setText(ui::text("已读取 ")+juce::String(catalog.tones().size())+ui::text(" 个音色 · 下载量为次数"),juce::dontSendNotification);pageLabel.setText(juce::String(catalog.page())+" / "+juce::String(catalog.pages()),juce::dontSendNotification);
    auto& data=catalog.detail();bool ready=data.tone.id>0 && !catalog.isDetailLoading();if(data.tone.id!=detailId || (ready && captures.getNumItems()==0)){detailId=data.tone.id;captures.clear(juce::dontSendNotification);if(ready){for(auto& m:data.models)if(m.id>0 && ((data.tone.format=="nam" && m.extension()==".nam") || (data.tone.format=="ir" && m.extension()==".wav")))captures.addItem(m.name+(m.architectureVersion.isEmpty()?juce::String():"  ["+m.architectureVersion+"]")+(m.size.isEmpty()?juce::String():"  "+m.size),m.id);if(captures.getNumItems()>0)captures.setSelectedId(captures.getItemId(0),juce::dontSendNotification);}}
    auto info=ready?description(data.tone):ui::text("选择一条音色查看说明与捕获。悬停音色卡片可查看完整热度数据。");if(detail.getText()!=info)detail.setText(info,false);bool playable=connected && !toneLoading && catalog.isDetailReady() && ready && (data.tone.format=="nam" || data.tone.format=="ir") && captures.getSelectedId()>0;bool loginLoad=!connected && !demo && !toneLoading && ready && (data.tone.format=="nam" || data.tone.format=="ir");add.setEnabled(playable || loginLoad);replace.setEnabled(playable || loginLoad);replace.setButtonText(ui::text(loginLoad?"登录并加载":"加载 / 替换"));captures.setEnabled(playable);viewSource.setEnabled(ready && !demo);share.setEnabled(ready && !demo);favorite.setEnabled(connected && ready && !catalog.isFavoriting());favorite.setButtonText(ui::text(data.tone.isFavorite?"已收藏":"收藏"));favorite.setToggleState(data.tone.isFavorite,juce::dontSendNotification);favorite.setTooltip(ui::text("与 TONE3000 账号收藏同步"));captures.setTooltip(captures.getText());auto modelIndex=captures.getSelectedItemIndex();previousCapture.setEnabled(playable && modelIndex>0);nextCapture.setEnabled(playable && modelIndex+1<captures.getNumItems());
    if(catalog.error().status || catalog.error().message.isNotEmpty())state.setText(catalogError(catalog.error()),juce::dontSendNotification);else if(catalog.detailError().status || catalog.detailError().message.isNotEmpty())state.setText(catalogError(catalog.detailError()),juce::dontSendNotification);else if(toneLoading)state.setText(ui::text("正在下载、校验并加载…"),juce::dontSendNotification);else if(catalog.isLoading())state.setText(ui::text("正在读取目录…"),juce::dontSendNotification);else if(catalog.isDetailLoading())state.setText(ui::text("正在获取全部捕获…"),juce::dontSendNotification);else if(!connected && !demo)state.setText(ui::text("免登录预览热门；搜索与加载请登录。"),juce::dontSendNotification);else if(ready && !playable && !demo)state.setText(ui::text("该格式可浏览；当前直接加载 NAM / IR。"),juce::dontSendNotification);else state.setText(ui::text("单击看详情 · 双击加载 · 拖到卡片替换"),juce::dontSendNotification);
    empty.setVisible(!filtersExpanded && !accountExpanded && catalog.tones().isEmpty());empty.setText(ui::text(catalog.isLoading()?"正在读取 TONE3000…":!connected && !demo?"登录后浏览完整在线目录。\n已有账号设置会自动保留。":started?"没有结果，可清除或调整筛选。":"搜索音色，或从完整目录开始浏览。"),juce::dontSendNotification);repaint();
}
juce::String OnlineBrowser::getTooltipForRow(int row){if(row<0 || row>=getNumRows())return {};auto& t=catalog.tones().getReference(row);return t.title+"\n"+toneFacts(t)+"\n"+t.user.creatorName()+ui::text(" · ")+t.publishedAt.substring(0,10);}
void OnlineBrowser::paintListBoxItem(int row,juce::Graphics& g,int w,int h,bool selected){
    if(row<0 || row>=getNumRows())return;auto& t=catalog.tones().getReference(row);auto card=juce::Rectangle<float>(2,6,float(w-4),float(h-12));g.setColour(selected?ui::selected:ui::panel);g.fillRoundedRectangle(card,16);g.setColour(selected?ui::accent.withAlpha(.6f):ui::line.withAlpha(.75f));g.drawRoundedRectangle(card.reduced(.5f),16,selected?1.5f:1.f);paintArtwork(g,{16,20,96,104},artwork->get(t.images.isEmpty()?juce::String():t.images[0]),t.gear);
    int x=128,tw=w-x-16;g.setColour(ui::ink);g.setFont(ui::font(16));g.drawFittedText(t.title,x,18,tw,40,juce::Justification::topLeft,2);g.setColour(ui::muted);g.setFont(ui::font(13));g.drawText(ui::text(t.gear)+ui::text(" · ")+badge(t),x,64,tw,20,juce::Justification::centredLeft);
    g.setColour(ui::accent);g.setFont(ui::font(13));auto popularity=compactCount(t.downloadsCount)+ui::text(" 下载 · ")+juce::String(t.format=="ir"?t.irsCount:t.modelsCount)+ui::text(" 捕获 · ")+compactCount(t.favoritesCount)+ui::text(" 收藏");g.drawText(popularity,x,86,tw,22,juce::Justification::centredLeft);
    paintArtwork(g,{x,112,20,20},artwork->get(t.user.avatarUrl),{},true);g.setColour(ui::muted);g.setFont(ui::font(13));g.drawText(t.user.creatorName()+(t.user.isVerified?ui::text(" ✓"):juce::String())+ui::text(" · ")+publishedLabel(t.publishedAt),x+28,110,tw-28,22,juce::Justification::centredLeft);
}
void OnlineBrowser::selectedRowsChanged(int row){if(!updating && !demo && row>=0 && row<getNumRows())catalog.select(catalog.tones()[row].id,!client.isConnected());}
void OnlineBrowser::listBoxItemDoubleClicked(int row,const juce::MouseEvent&){if(demo || row<0 || row>=getNumRows())return;auto& t=catalog.tones().getReference(row);load(t.id,t.id==catalog.detail().tone.id?captures.getSelectedId():0,chooseTarget?chooseTarget(t.format):juce::String());}
juce::var OnlineBrowser::getDragSourceDescription(const juce::SparseSet<int>& rows){if(demo || rows.isEmpty())return {};auto row=rows[0];if(row<0 || row>=getNumRows())return {};auto id=catalog.tones()[row].id;return "t3k-tone:"+juce::String(id)+":"+juce::String(id==catalog.detail().tone.id?captures.getSelectedId():0);}
void OnlineBrowser::replaceSelected(){auto& t=catalog.detail().tone;if(t.id>0)load(t.id,captures.getSelectedId(),chooseTarget?chooseTarget(t.format):juce::String());}
